set-variable.value:
#[import substringAfter, substringBefore from dw::core::Strings

// Parse URI
var removeBasePathAndQP = substringAfter(attributes.requestUri, p('application.base-path'))
       then (
        if ($ contains "?") substringBefore($, "?")
        else $
       )
var requestName = "$(attributes.method) $(removeBasePathAndQP)"

output application/json
---
{
 correlationId: attributes.headers.'x-root-correlation-id' default correlationId,
 flowId: uuid(),
 startStep: "Start $(requestName) flow",
 endStep: "Operation on $(requestName) completed successfully",
 endpoint: removeBasePathAndQP
}]

logger.message:
#[%dw 2.0
output application/json
---
{
    step: vars.metadata.startStep,
    data: {
        business: attributes.queryParams ++ {},
        technical: {
            flowId: vars.metadata.flowId,
            correlationId: vars.metadata.correlationId
        }
    }
}]

#[%dw 2.0
output application/json
---
{
 step: vars.metadata.endStep,
 data: {
  business: {},
  technical:{
   results: payload - "data"
  }
 }
}]

